#!/usr/bin/env python3
"""Linux Lab - echtes Terminal in deiner Ubuntu-VM (nur Python-Standardbibliothek).
Start:  python3 labserver.py            (nur in der VM erreichbar)
        python3 labserver.py --source https://raw.githubusercontent.com/USER/REPO/main   (Auto-Update)
        python3 labserver.py --host 0.0.0.0   (auch vom Host-PC erreichbar)
Aufgaben laufen in ~/linuxlab/home (wird bei jeder Aufgabe neu aufgebaut),
die Freie VM in ~/linuxlab/free (bleibt erhalten, dort funktioniert auch sudo)."""
import argparse, base64, fcntl, json, os, pty, secrets, shutil, signal, struct, subprocess, termios, threading, time, zlib, hashlib, sys, urllib.request
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlparse, parse_qs

ap = argparse.ArgumentParser()
ap.add_argument('--host', default='127.0.0.1'); ap.add_argument('--port', type=int, default=8000)
ap.add_argument('--root', default=os.path.expanduser('~/linuxlab'))
ap.add_argument('--token', help='fester Zugangs-Token (sonst wird einer in ROOT/token gespeichert)')
ap.add_argument('--source', help='Basis-URL fuer Auto-Updates, z. B. https://raw.githubusercontent.com/USER/REPO/main')
ap.add_argument('--interval', type=int, default=60, help='Update-Pruefung in Sekunden')
ap.add_argument('--no-free', action='store_true', help='Freie VM (Shell ohne Aufgabe) abschalten')
A = ap.parse_args()
ROOT = os.path.abspath(A.root); HOME = ROOT + '/home'; FREE = ROOT + '/free'; HIST = ROOT + '/history'
HERE = os.path.dirname(os.path.abspath(__file__)); os.makedirs(ROOT, exist_ok=True)
TF = ROOT + '/token'; STATE = ROOT + '/state.json'
if A.token:
    TOKEN = A.token
else:
    if not os.path.exists(TF):
        with open(os.open(TF, os.O_WRONLY | os.O_CREAT, 0o600), 'w') as f: f.write(secrets.token_urlsafe(24))
    TOKEN = open(TF).read().strip()
# Terminal-Fenster (xterm.js 5.3.0, MIT-Lizenz) ist eingebettet, damit kein Internet noetig ist
ASSETS = {k: zlib.decompress(base64.b64decode(v)) for k, v in {
    'xterm@5.3.0/css/xterm.css': '',
    'xterm@5.3.0/lib/xterm.js': '',
    'xterm-addon-fit@0.8.0/lib/xterm-addon-fit.js': '',
}.items()}


class Shell:
    def __init__(s):
        s.p = None; s.m = -1; s.buf = bytearray(); s.cv = threading.Condition(); s.ep = 0; s.home = HOME

    def start(s, home):
        s.stop(); os.makedirs(home, exist_ok=True); open(HIST, 'w').close(); s.home = home
        m, sl = pty.openpty()
        env = dict(os.environ, HOME=home, TERM='xterm-256color', HISTFILE=HIST, PROMPT_COMMAND='history -a',
                   PS1='\\u@lab:\\w\\$ ')
        s.p = subprocess.Popen(['bash', '--norc', '-i'], stdin=sl, stdout=sl, stderr=sl, cwd=home, env=env,
                               start_new_session=True, close_fds=True)
        os.close(sl)
        with s.cv:
            s.m = m; s.buf = bytearray(); s.ep += 1; s.cv.notify_all(); ep = s.ep
        threading.Thread(target=s.read, args=(m, ep), daemon=True).start()

    def read(s, m, ep):
        while True:
            try:
                d = os.read(m, 4096)
            except OSError:
                break
            if not d:
                break
            with s.cv:
                if ep != s.ep:
                    break
                s.buf += d; s.cv.notify_all()

    def stop(s):
        if s.p and s.p.poll() is None:
            try: os.killpg(s.p.pid, signal.SIGKILL)
            except Exception: pass
        if s.m >= 0:
            try: os.close(s.m)
            except Exception: pass
        s.p = None; s.m = -1


sh = Shell()


def bg_kill():
    subprocess.run(['pkill', '-f', '^backup\\.sh'], stderr=subprocess.DEVNULL)


def bg_start():
    bg_kill()
    subprocess.Popen(['bash', '-c', 'exec -a backup.sh sleep 7200'], start_new_session=True,
                     stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)


def bg_pid():
    r = subprocess.run(['pgrep', '-f', '^backup\\.sh'], capture_output=True, text=True)
    return int(r.stdout.split()[0]) if r.stdout.split() else 0


def setup(files):
    shutil.rmtree(HOME, ignore_errors=True); os.makedirs(HOME)
    for f in files:
        p = os.path.normpath(f.get('p', ''))
        if not p or p.startswith('..') or os.path.isabs(p):
            continue
        full = os.path.join(HOME, p)
        if f.get('t') == 'd':
            os.makedirs(full, exist_ok=True)
        else:
            os.makedirs(os.path.dirname(full), exist_ok=True)
            with open(full, 'w', encoding='utf-8') as fh: fh.write(f.get('c', ''))
            os.chmod(full, int(f.get('m', '644'), 8))


def snap():
    base = sh.home; files = []
    for d, ds, fs in os.walk(base):
        ds.sort()
        for n in ds + sorted(fs):
            p = os.path.join(d, n); st = os.lstat(p); isd = os.path.isdir(p) and not os.path.islink(p)
            e = {'p': os.path.relpath(p, base), 't': 'd' if isd else 'f', 'm': '%03o' % (st.st_mode & 0o777)}
            if not isd:
                try:
                    with open(p, encoding='utf-8') as fh: e['c'] = fh.read(200000)
                except Exception:
                    e['c'] = ''
            files.append(e)
        if len(files) > 3000: break
    try: cwd = os.readlink('/proc/%d/cwd' % sh.p.pid)
    except Exception: cwd = base
    try: hist = open(HIST, encoding='utf-8', errors='replace').read().splitlines()
    except Exception: hist = []
    return {'files': files, 'cwd': cwd, 'home': base, 'hist': hist, 'bg': bg_pid()}


def tok_ok(x):
    try: return secrets.compare_digest(x, TOKEN)
    except Exception: return False


def vhash():
    try: return hashlib.sha256(open(os.path.join(HERE, 'linux-lab.html'), encoding='utf-8').read().encode()).hexdigest()[:12]
    except Exception: return ''


def fetch(url):
    with urllib.request.urlopen(urllib.request.Request(url, headers={'User-Agent': 'linuxlab'}), timeout=20) as r:
        return r.read(3000000)


def swap(path, data):
    with open(path + '.new', 'wb') as f: f.write(data)
    os.replace(path + '.new', path)


def updater():
    base = A.source.rstrip('/') + '/'; me = os.path.abspath(__file__)
    while True:
        time.sleep(A.interval)
        try:
            h = fetch(base + 'linux-lab.html'); hp = os.path.join(HERE, 'linux-lab.html')
            if b'Linux Lab' in h and b'</html>' in h and h != open(hp, 'rb').read():
                swap(hp, h); print('Update: linux-lab.html aktualisiert', flush=True)
            sv = fetch(base + 'labserver.py')
            if sv != open(me, 'rb').read():
                compile(sv, 'labserver.py', 'exec'); swap(me, sv)
                print('Update: labserver.py aktualisiert, starte neu ...', flush=True)
                sh.stop(); bg_kill(); os.execv(sys.executable, [sys.executable] + sys.argv)
        except Exception as e:
            print('Update-Pruefung fehlgeschlagen:', e, flush=True)


class H(BaseHTTPRequestHandler):
    def log_message(s, *a): pass

    def out(s, body, code=200, ct='application/json'):
        b = body if isinstance(body, bytes) else json.dumps(body).encode()
        s.send_response(code); s.send_header('Content-Type', ct); s.send_header('Content-Length', str(len(b)))
        s.send_header('Cache-Control', 'no-store'); s.end_headers(); s.wfile.write(b)

    def ok(s): return tok_ok(s.headers.get('X-Token', ''))

    def do_GET(s):
        u = urlparse(s.path); q = parse_qs(u.query)
        if u.path.startswith('/x/') and u.path[3:] in ASSETS:
            n = u.path[3:]
            return s.out(ASSETS[n], 200, 'text/css' if n.endswith('css') else 'application/javascript')
        if u.path == '/':
            if not tok_ok(q.get('t', [''])[0]): return s.out(b'Zugriff nur mit Token-Link aus dem Terminal', 403, 'text/plain; charset=utf-8')
            h = open(os.path.join(HERE, 'linux-lab.html'), encoding='utf-8').read()
            v = hashlib.sha256(h.encode()).hexdigest()[:12]
            h = h.replace('https://cdn.jsdelivr.net/npm/', '/x/')
            h = h.replace('<head>', '<head><script>window.LAB=' + json.dumps({'token': TOKEN, 'v': v}) + '</script>', 1)
            return s.out(h.encode(), 200, 'text/html; charset=utf-8')
        if not s.ok(): return s.out({'error': 'token'}, 403)
        if u.path == '/api/out':
            ep = int(q['ep'][0]); pos = int(q['pos'][0]); end = time.time() + 15
            with sh.cv:
                if ep != sh.ep: pos = 0
                while len(sh.buf) <= pos and ep == sh.ep and time.time() < end: sh.cv.wait(1)
                if ep != sh.ep: pos = 0
                d = bytes(sh.buf[pos:])
                return s.out({'ep': sh.ep, 'pos': pos + len(d), 'data': base64.b64encode(d).decode()})
        if u.path == '/api/snap': return s.out(snap())
        if u.path == '/api/version': return s.out({'v': vhash()})
        if u.path == '/api/state':
            try: return s.out(json.load(open(STATE)))
            except Exception: return s.out({})
        s.out({'error': 'nicht gefunden'}, 404)

    def do_POST(s):
        if not s.ok(): return s.out({'error': 'token'}, 403)
        body = s.rfile.read(int(s.headers.get('Content-Length', 0)))
        u = urlparse(s.path).path
        if u == '/api/in':
            if sh.p is None or sh.p.poll() is not None: sh.start(sh.home)
            os.write(sh.m, body); return s.out({})
        j = json.loads(body or b'{}')
        if u == '/api/resize':
            if sh.m >= 0: fcntl.ioctl(sh.m, termios.TIOCSWINSZ, struct.pack('HHHH', j['r'], j['c'], 0, 0))
            return s.out({})
        if u == '/api/state':
            open(STATE, 'w').write(json.dumps(j)[:1000000]); return s.out({})
        if u == '/api/task':
            if j.get('free'):
                if A.no_free: return s.out({'error': 'free'}, 403)
                bg_kill(); sh.start(FREE)
            else:
                setup(j.get('files', []))
                bg_start() if j.get('bg') else bg_kill()
                sh.start(HOME)
            return s.out({'ep': sh.ep})
        s.out({'error': 'nicht gefunden'}, 404)


if __name__ == '__main__':
    srv = ThreadingHTTPServer((A.host, A.port), H)
    ip = A.host
    if ip == '0.0.0.0':
        try: ip = subprocess.check_output(['hostname', '-I'], text=True).split()[0]
        except Exception: ip = 'VM-IP'
    print('\nLinux Lab laeuft. Oeffne diesen Link im Browser:\n\n  http://%s:%d/?t=%s\n\n(Beenden mit Strg+C)' % (ip, A.port, TOKEN))
    if A.source: threading.Thread(target=updater, daemon=True).start()
    try: srv.serve_forever()
    except KeyboardInterrupt: pass
    finally: sh.stop(); bg_kill()
